mapper.select:
SELECT DISTINCT a.*, c.name as category_name, u.nickname as author_name FROM t_article a LEFT JOIN t_category c ON a.category_id = c.id LEFT JOIN t_user u ON a.user_id = u.id LEFT JOIN t_article_tag at ON a.id = at.article_id WHERE a.deleted = 0 AND a.status = 1
AND a.category_id = #{categoryId}
AND at.tag_id = #{tagId}
AND (a.title LIKE CONCAT('%', #{keyword}, '%') OR a.content LIKE CONCAT('%', #{keyword}, '%'))
AND a.user_id = #{userId}
ORDER BY a.create_time DESC
